package com.farika.soundflow;
import android.app.*;import android.content.*;import android.database.sqlite.*;import android.graphics.*;import android.net.*;import android.os.*;import android.view.*;import android.widget.*;
import androidx.media3.datasource.*;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import java.io.*;import java.lang.reflect.*;import java.security.*;import java.util.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=28,manifest=Config.NONE,application=android.app.Application.class)
public class FlowRegressionTest {
 Context c;Activity a;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.deleteDatabase("downloads.db");c.getSharedPreferences("profile",0).edit().putString("id","123").commit();a=Robolectric.buildActivity(Activity.class).setup().get();Provider provider=new Provider("VolnaSyntheticKeyStore",1.0,"test only"){};provider.put("KeyStore.AndroidKeyStore",WarmWriterTest.MemoryStore.class.getName());Security.insertProviderAt(provider,1);}
 @After public void cleanup(){PlaybackService.instance=null;a.finish();Security.removeProvider("VolnaSyntheticKeyStore");}
 Library.Track track(String id)throws Exception{Library.Track t=new Library.Track("sc:"+id,"track "+id,"artist",12000,false);t.remote=new JSONObject().put("id",id).put("downloadable",true);return t;}
 void plan(SyncDb db,String id,String state)throws Exception{db.ensure("123",id,id,"own");db.snapshot("123",id,Arrays.asList(track("456")));db.state("123",id,"456",state,"");}
 NetworkCapabilities caps(int transport,boolean internet,boolean unmetered){NetworkCapabilities n=new NetworkCapabilities();org.robolectric.shadows.ShadowNetworkCapabilities shadow=Shadows.shadowOf(n);shadow.clearCapabilities();shadow.addTransportType(transport);if(internet)shadow.addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);if(unmetered)shadow.addCapability(NetworkCapabilities.NET_CAPABILITY_NOT_METERED);return n;}
 @Test public void wifiRejectsUnmeteredCellular(){NetworkCapabilities caps=caps(NetworkCapabilities.TRANSPORT_CELLULAR,true,true);assertFalse(AutoDownloads.allowed(caps,true));assertTrue(AutoDownloads.allowed(caps,false));}
 @Test public void wifiAllowsMeteredWifi(){assertTrue(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_WIFI,true,false),true));}
 @Test public void noInternetNeverAllowsAuto(){assertFalse(AutoDownloads.allowed((NetworkCapabilities)null,false));assertFalse(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_WIFI,false,true),true));}
 @Test public void completedOneOffHiddenButDataRetained()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","READY");assertTrue(db.workPlans("123").isEmpty());assertEquals(1,db.tracks("123","p").size());}}
 @Test public void completedAutoVisible()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","READY");db.auto("123","p",true);assertEquals(1,db.workPlans("123").size());}}
 @Test public void errorWithoutAutoVisibleAndScheduled()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","BLOCKED");db.retry("123","p","456",System.currentTimeMillis()+3600000);assertEquals(1,db.workPlans("123").size());assertTrue(db.nextAutomaticRetry("123")>System.currentTimeMillis()+3000000);}}
 @Test public void interruptedManualVisibleAndScheduled()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","RUNNING");db.active("123","p",true);db.recoverInterrupted("123");assertEquals(1,db.workPlans("123").size());assertTrue(db.nextAutomaticRetry("123")>0);assertEquals(1,db.totals("123","p")[3]);}}
 @Test public void emptyActivePlanSurvivesRestart(){try(SyncDb db=new SyncDb(c)){db.ensure("123","p","p","own");db.active("123","p",true);assertEquals(1,db.workPlans("123").size());assertTrue(db.nextAutomaticRetry("123")>0);}}
 @Test public void disabledCompletedPlanHidden()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","READY");db.auto("123","p",true);db.auto("123","p",false);db.active("123","p",false);assertTrue(db.workPlans("123").isEmpty());}}
 @Test public void cancelledPendingDoesNotKeepDownloading()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","PENDING");db.cancelPending("123","p");assertTrue(db.cancelled("123","p","456"));assertTrue(db.workPlans("123").isEmpty());assertEquals(0,db.nextAutomaticRetry("123"));}}
 @Test public void snapshotAddsNewAutoTracksWithoutLosingRetry()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","BLOCKED");db.retry("123","p","456",123456789);db.snapshot("123","p",Arrays.asList(track("456"),track("789")));assertEquals(2,db.tracks("123","p").size());assertEquals(123456789,db.retryAt("123","p","456"));assertEquals(2,db.totals("123","p")[0]);}}
 @Test public void sharedReferencesProtectCopies()throws Exception{try(SyncDb db=new SyncDb(c)){plan(db,"p","READY");assertFalse(db.otherReference("123","p","456"));plan(db,"q","READY");assertTrue(db.otherReference("123","p","456"));db.removePlan("123","p");assertEquals(1,db.plans("123",false).size());}}
 @Test public void v1DatabaseMigratesWithoutLosingRows()throws Exception{c.deleteDatabase("downloads.db");SQLiteDatabase old=c.openOrCreateDatabase("downloads.db",0,null);old.execSQL("CREATE TABLE plans(owner TEXT,id TEXT,title TEXT,kind TEXT,auto INTEGER DEFAULT 0,status TEXT DEFAULT '',PRIMARY KEY(owner,id))");old.execSQL("CREATE TABLE items(owner TEXT,plan TEXT,tid TEXT,pos INTEGER,data TEXT,state TEXT,error TEXT,retryAt INTEGER DEFAULT 0,PRIMARY KEY(owner,plan,pos))");old.execSQL("INSERT INTO plans(owner,id,title,kind,auto) VALUES('123','p','keep','own',1)");old.setVersion(1);old.close();try(SyncDb db=new SyncDb(c)){assertEquals("keep",db.plans("123",false).get(0).optString("title"));assertFalse(db.plans("123",false).get(0).optBoolean("active"));}}
 @Test public void repeatCyclesDifferForWaveAndPlaylist(){assertEquals(1,RepeatPolicy.next(0,false));assertEquals(0,RepeatPolicy.next(1,false));assertEquals(2,RepeatPolicy.next(1,true));assertEquals(0,RepeatPolicy.next(2,true));assertFalse(RepeatPolicy.wraps(false,true));assertTrue(RepeatPolicy.wraps(true,true));}
 @Test public void playlistRepeatContextSurvivesCheckpoint()throws Exception{Library lib=new Library(c);lib.upsert(track("456"));lib.save();assertTrue(PlaybackCheckpoint.save(c,Arrays.asList("sc:456"),0,3000,false,false,false,false,true,true));PlaybackCheckpoint.Snapshot row=PlaybackCheckpoint.read(c);assertNotNull(row);assertTrue(row.playlistContext);assertTrue(row.repeatPlaylist);assertEquals(3000,row.position);}
 @Test public void waveCheckpointCannotRestorePlaylistRepeat()throws Exception{Library lib=new Library(c);lib.upsert(track("456"));lib.save();PlaybackCheckpoint.save(c,Arrays.asList("sc:456"),0,0,false,false,false,false,false,true);assertFalse(PlaybackCheckpoint.read(c).repeatPlaylist);}
 @Test public void equalizerCanBeConfiguredBeforePlayback(){AudioEqualizer eq=new AudioEqualizer(c);assertFalse(eq.available());assertTrue(eq.enable(true));int freq=eq.frequencies()[0];assertTrue(eq.gain(freq,600));AudioEqualizer reopened=new AudioEqualizer(c);assertTrue(reopened.enabled());assertEquals(600,reopened.gain(freq));}
 @Test public void presetsAreIndependentAndWithinRange(){assertEquals(7,EqPresets.NAMES.length);for(int i=0;i<EqPresets.NAMES.length;i++){int[] gains=EqPresets.gains(i);assertEquals(5,gains.length);for(int n:gains)assertTrue(n>=-1200&&n<=1200);gains[0]=9999;assertNotEquals(9999,EqPresets.gains(i)[0]);}}
 @Test public void verticalFaderMapsTopAndBottom(){LinearLayout parent=new LinearLayout(a);VerticalFader f=new VerticalFader(a,"60Hz",0,value->{});parent.addView(f);a.setContentView(parent);f.layout(0,0,100,300);f.onTouchEvent(MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,50,0,0));assertEquals(1200,f.gain());f.onTouchEvent(MotionEvent.obtain(0,0,MotionEvent.ACTION_UP,50,300,0));assertEquals(-1200,f.gain());}
 @Test public void verticalFaderSupportsKeyboard(){VerticalFader f=new VerticalFader(a,"60Hz",0,value->{});f.onKeyDown(KeyEvent.KEYCODE_DPAD_UP,new KeyEvent(0,KeyEvent.KEYCODE_DPAD_UP));assertEquals(100,f.gain());}
 int count(View v,Class<?> type){int n=type.isInstance(v)?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)n+=count(((ViewGroup)v).getChildAt(i),type);return n;}
 @Test public void settingsEqualizerContainsFiveVerticalFaders(){View panel=EqualizerPanel.create(a);assertEquals(5,count(panel,VerticalFader.class));assertEquals(1,count(panel,Spinner.class));}
 @Test public void closedDpiTunnelIsDetectable()throws Exception{DpiTunnel tunnel=new DpiTunnel();assertTrue(tunnel.alive());tunnel.close();assertFalse(tunnel.alive());}
 @Test public void track404HasSpecificNonNetworkReason(){DownloadFault fault=DownloadFault.of(new ScApi.ApiError(404).at("TRACK"));assertEquals("TRACK_UNAVAILABLE",fault.code);assertFalse(fault.retry);assertEquals("HTTP_404",DownloadFault.of(new ScApi.ApiError(404).at("ORIGINAL")).code);}
 @Test(timeout=30000) public void original404FallsBackToClearAndSavesArtwork()throws Exception{
  Session.put(c,"OAuth SYNTHETIC_FLOW_TOKEN_12345","SYNTHETIC_FLOW_CLIENT_12345");Library.Track t=track("456");t.remote.put("artwork_url","https://i1.sndcdn.com/fixture-flow.jpg");final int[] calls={0,0};
  ScApi fake=new ScApi(c){public Library.Track freshTrack(Library.Track old){return old;}public File download(Library.Track old,OfflineStore.Progress progress)throws Exception{calls[0]++;throw new ScApi.ApiError(404).at("ORIGINAL");}public Stream playable(Library.Track old,boolean offline){calls[1]++;return new Stream("https://cf-media.sndcdn.com/fixture-flow.mp3",false,"",false,12000);}public Bitmap artwork(String url){return Bitmap.createBitmap(32,32,Bitmap.Config.ARGB_8888);}};
  OfflineStore store=new OfflineStore(c){protected ScApi api(){return fake;}protected DataSource.Factory networkSource(){return ()->new ByteArrayDataSource(new byte[8192]);}protected long measuredCache(DataSource.Factory d,String u){return 12000;}};
  Library.Track saved=store.save(t,new OfflineStore.Progress(){public boolean cancelled(){return false;}public void update(int p){}});assertEquals(1,calls[0]);assertEquals(1,calls[1]);assertNotNull(store.find(saved.uri));assertNotNull(OfflineArt.read(c,t.artwork()));try(OfflineStore.Open open=store.open(saved.uri)){assertFalse(open.drm);assertFalse(open.hls);}store.remove(saved.uri);
 }
}
